def unit_of_work(metadata=None, timeout=None):
    def decorator(f):
        @contextlib.contextmanager
        def unit_of_work_decorator(tx):
            if metadata:
                tx.metadata.update(metadata)
            t = time.time()

            try:
                yield f(tx)
            except Exception as e:
                print(f"Transaction {tx.id} failed: {e}")
                if tx.failpoint:
                    tx.failpoint()
                raise
            else:
                print(f"Transaction {tx.id} succeeded")            
            duration = time.time() - t
            if timeout is not None and duration > timeout:
                print(f"Transaction {tx.id} timed out after {duration} seconds")
                if tx.failpoint:
                    tx.failpoint()
                raise
        return unit_of_work_decorator
    return decorator

