def parse_version(s: str) -> tuple[int, ...]:
    i = 0
    while i < len(s) and s[i] != '.':
        i += 1
    num_str = s[:i]

    num_parts = num_str.split('.')
    num_parts = [int(x) for x in num_parts]

    return tuple(num_parts)

