    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.

        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        def get_exception_details(e, stack_level=0):
            if stack_level > max_level:
                return None
            details = f"{e.__class__.__name__}: {e}"
            if hasattr(e, '__traceback__'):
                for frame in e.__traceback__.traceback:
                    frame_info = f"at {frame.filename}:{frame.lineno}"
                    if frame_info not in details:
                        details += f",{frame_info}"
            return details if details else None

        def format_stack_path(frame):
            path_info = f"{frame.filename}:{frame.lineno}"
            if path_info not in details:
                details += f",{path_info}"
            return details

        try:
            exception_details = get_exception_details(e)
            if exception_details is None:
                return str(e)
            stack_path = format_stack_path(e.__traceback__.traceback[0])
            if stack_path is None:
                return exception_details
            if len(stack_path) > max_path_level:
                stack_path = stack_path[:max_path_level]
            return f"{exception_details}\nStack Path: {stack_path}"
        except Exception as e:
            return str(e)

