def extostr(e, max_level=30, max_path_level=5):
    def recur(stack, path):
        if not stack:
            return "No stack traces to format."

        frame = stack.pop()
        output = f"File: {frame.filename}, Line: {frame.lineno}, Function: {frame.function}"

        if path:
            parent_path = stack[-1]
            if path[-1] == parent_path:
                output += f", Class: {parent_path.class_name}"

        if frame.code_context:
            context = f"{frame.code_context[0][:frame.offset]} >> {frame.code_context[0][frame.offset:]} [from line {frame.code_context[1]}]"
            output += f", Context: {context}"

        if frame.exc_type:
            output += f", Exception: {frame.exc_type}"

        return output

    stack = traceback.extract_stack()[:max_level]
    path = traceback.extract_stack(timeout=max_path_level)
    return recur(stack, path)

