        if key not in d2:
            result[key] = copy.deepcopy(d1[key])
        elif level >= 0:
            child_diff = difference(d1[key], d2[key], level - 1)
            if child_diff:
                result[key] = child_diff

    for key in d2.keys():
        if key not in d1:
            result[key] = copy.deepcopy(d2[key])

    return result

