def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        if debug:
            print("Calling pretty method with indent:", indent)

        result = "  " * indent + str(self) + "\n"
        indent += 1

        for child in self.children:
            result += child.pretty(indent, debug)

        return result.strip()

def pretty(self, indent=0, debug=False):
    pretty = []

    for k, v in sorted(self.items()):
        pretty.append(' ' * indent + str(k))
        if not debug and isinstance(v, dict):
            pretty.append(pretty(v, indent + 2))
        else:
            pretty.append(' ' * (indent + 2) + str(v))
    if debug:
        return pretty
    return '\n'.join(pretty)

def pretty(self, indent=0, debug=False):
    result = ""
    for member in dir(self):
        if not member.startswith('__'):
            value = getattr(self, member)
            if isinstance(value, str):
                result += " " * indent + member + ": " + value + "\n"
            elif isinstance(value, (int, float)):
                result += " " * indent + member + ": " + str(value) + "\n"
            elif isinstance(value, dict):
                result += " " * indent + member + ":\n" + value.prettify(indent + 4, debug)
            elif isinstance(value, list):
                result += " " * indent + member + ": [\n"
                for item in value:
                    if isinstance(item, (int, float)):
                        result += " " * (indent + 8) + str(item) + ",\n"
                    else:
                        result += " " * (indent + 8) + item.prettify(indent + 8, debug) + ",\n"
                result += " " * indent + "],\n"
            elif callable(value) and hasattr(value, '__doc__'):
                result += " " * indent + member + ":\n" + " " * (indent + 4) + value.__doc__ + "\n"
            else:
                result += " " * indent + member + ": " + str(value) + "\n"
    return result

