    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """

    def absorb_expression(expr, other_expr):
        if expr is other_expr:
            return expr
        if expr == 0:
            return 0
        if other_expr == 0:
            return 0

        result = 0
        if expr >= 0 and other_expr >= 0:
            result = expr + other_expr
        elif expr <= 0 and other_expr <= 0:
            result = expr + other_expr
        elif expr > 0 > other_expr:
            result = expr + other_expr
        elif expr < 0 < other_expr:
            result = expr + other_expr

        return result

    result = [absorb_expression(expr, expr) for expr in args]
    return result

def absorb(self, args):
    absorb_result = []
    for i in range(len(args)):
        new_expression = args[i]
        for j in range(i, len(args)):
            if new_expression & (args[i] | args[j]) != 0:
                new_expression = new_expression & args[i]
            elif new_expression | (args[i] & args[j]) != 0:
                new_expression = new_expression | args[j]
    absorb_result.append(new_expression)
    return absorb_result

def absorb(self, args):
    def apply_absorption(x):
        # (A & (A | B)) = (A | A) = A
        return x | x

    def apply_negative_absorption(x):
        # (A & (~A | B)) = (A & A) = A | B
        return x | x

    result = []
    for arg in args:
        if isinstance(arg, tuple):
            # Apply absorption on the first element
            result.append(apply_absorption(arg[0]))
            # Apply negative absorption on the second element if it's not a tuple
            if not isinstance(arg[1], tuple):
                result.append(apply_negative_absorption(arg[1]))
        else:
            result.append(arg)
    return result

