def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    process_args = []
    if cwd is not None:
        process_args.append(f'cd {cwd}')
    if verbose:
        process_args.append('set -x')
    for command in commands:
        process_args.append(command)
    if hide_stderr:
        process_args.append('2>/dev/null')
    if env:
        envvars = ['='.join((var, value)) for var, value in env.items()]
        process_args.append(f'ENV={"; ".join(envvars)}')

    cmd = " && ".join(process_args)
    result = subprocess.run(cmd, args=args, shell=True, env=env)
    if verbose:
        print(f"Command: {cmd}")
        print(f"Return code: {result.returncode}")
    return result.stdout.decode('utf-8')

