func nextVersion(version string) string {
    versionInts := []int{}
    zeroPrefixed := true

    // Check if the version is zero-prefixed
    if version[0] == '0' {
        zeroPrefixed = true
        version = version[1:]
    }

    // Split the version into its parts
    parts := strings.Split(version, ".")

    // Convert the parts to integers
    for _, part := range parts {
        if part == "" {
            versionInts = append(versionInts, 0)
        } else {
            versionInts = append(versionInts, numbersToInt(part))
        }
    }

    // Increment the last part
    versionInts[len(versionInts)-1]++

    // If increment caused a carry, reset the previous part
    if versionInts[len(versionInts)-1] > 90 {
        versionInts[len(versionInts)-1] = 0
        if zeroPrefixed {
            versionInts = append([]int{1}, versionInts...)
        } else {
            versionInts[len(versionInts)-2]++
        }
    }

