def deep_merge_nodes(nodes):
    def merge_values(node1, node2):
        if isinstance(node1, yaml.SequenceNode) and isinstance(node2, yaml.SequenceNode):
            # Merge sequences
            result = node1.coerce_value()
            for item in node2:
                if item not in result:
                    result.append(item)
            return result
        elif isinstance(node1, yaml.MappingNode) and isinstance(node2, yaml.MappingNode):
            # Merge mappings
            result = node1.coerce_value()
            for key, value in node2.items():
                if key in result:
                    # If key already exists and both values are MappingNodes, deep merge
                    if isinstance(result[key], yaml.MappingNode) and isinstance(value, yaml.MappingNode):
                        result[key] = merge_values(result[key], value)
                    # Otherwise, use the latter value
                    else:
                        result[key] = merge_values(result[key], merge_values(value, None))
                else:
                    result[key] = merge_values(None, value)
            return result
        elif isinstance(node1, yaml.ScalarNode) and isinstance(node2, yaml.ScalarNode):
            # Merge scalars
            return node2.coerce_value()
        return None

    merged_nodes = []
    keys = set()
    for key, value in nodes:
        if key in keys:
            existing_value = next((n for n, val in nodes if n == key), None)
            merged_nodes.append((key, merge_values(existing_value, value)))
        else:
            merged_nodes.append((key, value))
            keys.add(key)

    return merged_nodes

