def paging(response: list, max_results: int) -> Generator[list, None, None]:
    current_page = 0
    while True:
        page = response[current_page * max_results: (current_page + 1) * max_results]
        if not page:
            break
        yield page
        current_page += 1

def paging(response, max_results):
    start = 0
