def get_repo_archive(url: str, destination_path: Path) -> Path:
    def download_and_extract_tar(url, output_path):
        response = requests.get(url)
        response.raise_for_status()  # Raise an HTTPError if the request was unsuccessful
        with open(output_path, 'wb') as file:
            file.write(response.content)

    path_repos = Path(__file__).parent / "repos"

    for subpath in path_repos.iterdir():
        if subpath.is_file():
            continue
        elif subpath.is_dir():
            for tar_path in subpath.iterdir():
                if tar_path.suffix == '.tar.gz':
                    output_path = destination_path / tar_path.stem
                    download_and_extract_tar(tar_path, output_path)
                    return output_path
    return None  # This line should never be reached if the url is valid

