public static String getIgnoredFiles() {
    try {
        // Use the git command to obtain the file names
        List<String> fileNames = new ArrayList<>();
        Process process = Runtime.getRuntime().exec("git ls-files --ignored");

        // Read from the standard error stream to capture any output and handle it
        List<String> errorLines = process.getErrorStream().lines().collect(Collectors.toList());
        if (!errorLines.isEmpty()) {
            System.out.println("Error executing git ls-files:");
            for (String error : errorLines) {
                System.err.println(error);
            }
        }

        // Read from the standard input stream to capture the output
        List<String> outputLines = process.getInputStream().lines().collect(Collectors.toList());
        for (String output : outputLines) {
            fileNames.add(output);
        }

        // Sort the list of files and return them as a single string
        Collections.sort(fileNames);
        return String.join(", ", fileNames);
    } catch (Exception e) {
        e.printStackTrace();
        return null;
    }
}

