def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    start = image_href.find('/r/') + 2
    end = image_href.find('/', start) if '/' in image_href[start:] else None
    netloc = image_href[start:end] if end is not None else None
    use_ssl = image_href.endswith('.jpg') or image_href.endswith('.png') if end is not None else None
    if not image_href.startswith('http://') and use_ssl:
        image_href = 'https://' + image_href
    image_id = image_href.replace('http://', '')
    return (image_id, netloc, use_ssl)

