import rdflib

def find_roots(graph: rdflib.Graph, prop: rdflib.URIRef, roots: Optional[set[rdflib.Node]] = None) -> set[rdflib.Node]:
    if roots is None:
        roots = set()

    stack = [node for node in graph.subjects(predicate=prop)]
    visited = set(stack)
    while stack:
        current = stack.pop()
        if current in roots:
            continue
        roots.add(current)
        for parent in graph.objects(subject=current, predicate=prop):
            if parent not in visited:
                stack.append(parent)
                visited.add(parent)
    return roots

