def parse_diaspora_webfinger(document: str) -> Dict:
    # Initialize parsing data
    result = {}
    headers = {}

    # Check if the document is in JSON format
    if document.startswith("\ufeff{}"):  #.some UTF-8 byte order mark for JSON files
        try:
            data = json.loads(document)
            # Extract attributes from JSON
            result["protocols"] = data.get("protocols", [])
            result["subject"] = data.get("subject", [])
            result["aliases"] = data.get("aliases", [])
            # Convert RDF to key-value pair
            g = Graph()
            g.parse(data.encode("utf-8"), format="json-ld")
            for s, p, o in g:
                result[o] = s
        except json.JSONDecodeError:
            headers = {"error": "Invalid JSON format"}

    # Check if the document is in XRD format
    elif document.startswith("<"):
        try:
            doc = Graph()
            doc.parse(data, format="turtle")
            # Extract RDF to key-value pair
            for s, p, o in doc:
                result[o] = s
            # Convert RDF to key-value pair
            g = Graph()
            g.parse(data, format="json-ld")
            for s, p, o in g:
                result[o] = s
        except Exception as e:
            headers = {"error": f"Error parsing XRD: {e}"}

    return result, headers

