    :param values_dict: The dict of with arguments
   """
    if self.cli_args:
        constraints = {
            'vce': (
                ('cpu_usage', int),
                ('cpu_percent', float),
            ),
            'treeset': (
                ('max_entries', int),
                ('age_limit_hrs', int),
            ),
        }

        value = values_dict.pop(parser_name)

        for arg, type_info in constraints.get(parser_name, []):
            if arg in value:
                values_dict[arg] = type_info[1](value[arg])

